-- Synthetic ServicePoint data. New table only; no DROP or overwrite.
CREATE TABLE servicepoint_cases (
  Case_ID VARCHAR(12) PRIMARY KEY,
  Opened_Date DATE,
  Month VARCHAR(7),
  Channel VARCHAR(20),
  Contact_Reason VARCHAR(30),
  Team VARCHAR(30),
  Initial_Wait_Minutes DECIMAL(10,2),
  Initial_Handling_Minutes DECIMAL(10,2),
  Resolution_Hours DECIMAL(10,2),
  Resolved_On_First_Contact VARCHAR(3),
  Repeat_Contacts_7_Days INTEGER,
  Complaint VARCHAR(3),
  Escalated VARCHAR(3),
  CSAT_Score INTEGER,
  Source_Type VARCHAR(12)
);

